function validate([head]) {
  if (!Array.isArray(head) || head.length < 2 || head.length > 100) return 'The list holds 2 to 100 nodes.';
  if (head.length % 2 !== 0) return 'The list needs an even number of nodes.';
  for (let i = 0; i < head.length; i++) {
    const v = head[i];
    if (!Number.isInteger(v) || v < 1 || v > 100) return 'Each node value is an integer from 1 to 100.';
    if (v % 2 !== i % 2) return 'Even positions need even values and odd positions need odd values.';
  }
  return null;
}

