function gameResult(head) {
  let even = 0;
  let odd = 0;
  for (let node = head; node !== null; node = node.next.next) {
    const evenValue = node.val;
    const oddValue = node.next.val;
    if (evenValue > oddValue) {
      even++;
    } else {
      odd++;
    }
  }
  if (even > odd) {
    return "Even";
  }
  if (odd > even) {
    return "Odd";
  }
  return "Tie";
}

