function gameResult(head) {
  const values = [];
  for (let p = head; p; p = p.next) values.push(p.val);
  let score = 0;
  values.forEach((v, i) => {
    if (i % 2 === 0) score += Math.sign(v - values[i + 1]);
  });
  return score > 0 ? "Even" : score < 0 ? "Odd" : "Tie";
}

