function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const pairs = size === 'large' ? 50 : int(1, 6);
  const top = size === 'large' ? 50 : (rand() < 0.5 ? 6 : 50);
  const list = [];
  for (let p = 0; p < pairs; p++) {
    list.push(2 * int(1, top));
    list.push(2 * int(1, top) - 1);
  }
  return [list];
}
